package gateway

import (
	"context"
	"errors"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/DIYgod/pinky/internal/demo"
	"github.com/DIYgod/pinky/internal/driver"
)

const mediaDetail = "An app on the iPhone is using the camera or microphone, and iOS does not allow mirroring the screen then. " +
	"Pinky connects by itself once the camera and microphone are free."

// mediaProvider lists an iPhone as the iOS driver does while an app on it
// uses the camera or microphone: online until an open finds the stream
// refused, then needing the media_in_use step at every listing while its
// session tries the stream again, and online once the camera and
// microphone are free, when the next open takes that session over.
type mediaProvider struct {
	dev     *demo.Device
	mu      sync.Mutex
	inUse   bool // an app holds the camera or microphone
	waiting bool // an open found it so, and its session waits
	opens   int
}

func (p *mediaProvider) Platform() driver.Platform { return driver.IOS }

func (p *mediaProvider) List(context.Context) ([]driver.Info, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	info := driver.Info{ID: "ip", Platform: driver.IOS, Name: "iPhone 15 Plus", Model: "iPhone 15 Plus", OSVersion: "27.2",
		Connection: "usb", Backend: "coredevice", State: driver.StateOnline}
	if p.waiting && p.inUse {
		info.State, info.Setup, info.Detail = driver.StateNeedsSetup, driver.SetupMediaInUse, mediaDetail
	}
	return []driver.Info{info}, nil
}

func (p *mediaProvider) Open(context.Context, string) (driver.Device, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.opens++
	if p.inUse {
		p.waiting = true
		return nil, &driver.SetupError{Setup: driver.SetupMediaInUse, Detail: mediaDetail,
			Err: errors.New("start display stream (display 1): The device microphone or camera is currently in use. (com.apple.dt.CoreDeviceError 9022)")}
	}
	p.waiting = false
	return p.dev, nil
}

func (p *mediaProvider) free() {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.inUse = false
}

func (p *mediaProvider) openCount() int {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.opens
}

// TestMediaInUseStep: an iPhone whose stream iOS refuses while an app uses
// the camera or microphone needs the media_in_use step from the first open
// on, and keeps needing it, round after round of discovery, without being
// opened again or going online in between. An agent hears the step and its
// words; once the camera and microphone are free, the phone opens.
func TestMediaInUseStep(t *testing.T) {
	p := &mediaProvider{dev: demo.NewDevice("ip", "iPhone 15 Plus", driver.IOS), inUse: true}
	g := stepGateway(t, p)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	events := g.Subscribe(ctx)

	v := viewUntil(t, g, "ip", "the step", func(v DeviceView) bool { return v.Info.Setup == driver.SetupMediaInUse })
	if v.Status != DeviceNeedsSetup || v.StatusLine != "Camera or microphone in use" || v.Info.State != driver.StateNeedsSetup || v.Info.Detail != mediaDetail {
		t.Fatalf("the step: %+v", v)
	}

	// Many discoveries (every 20 ms) later: the same step all along, the
	// phone opened once, and no event about it.
	for len(events) > 0 {
		<-events
	}
	for range 30 {
		for _, v := range g.Devices() {
			if v.Info.ID == "ip" && (v.Status != DeviceNeedsSetup || v.Info.Setup != driver.SetupMediaInUse) {
				t.Fatalf("the step flickered: %q, %+v", v.Status, v.Info)
			}
		}
		time.Sleep(10 * time.Millisecond)
	}
	if n := p.openCount(); n != 1 {
		t.Errorf("opened %d times while it waited; want once", n)
	}
	for len(events) > 0 {
		if e := <-events; e.DeviceID == "ip" && (e.Kind == EventDevices || e.Kind == EventNeeds) {
			t.Errorf("an event while nothing changed: %+v", e)
		}
	}
	cu, err := g.Checkup(ctx, "ip")
	if err != nil {
		t.Fatal(err)
	}
	if auth, _ := checkByID(cu, driver.CheckAuthorized); auth.Status != driver.CheckFail || auth.Fix != driver.SetupMediaInUse || auth.Detail != mediaDetail {
		t.Errorf("the checkup's step: %+v", auth)
	}

	// An agent hears the step, what to do, and how to ask the person.
	s := g.OpenSession(AgentInfo{Name: "Claude Code"})
	defer s.Close()
	res := s.Connect(ctx, ConnectRequest{Task: "Photos"})
	if res.Status != StatusNeedsSetup || res.Setup != driver.SetupMediaInUse || !strings.Contains(res.Message, mediaDetail) ||
		!strings.Contains(res.Message, "phone_handoff") || !strings.Contains(res.Message, "call") {
		t.Fatalf("connecting: %+v", res)
	}

	// Free: online, and opened.
	p.free()
	waitOnline(t, g, "ip")
	if v := viewUntil(t, g, "ip", "online", func(v DeviceView) bool { return v.Status != DeviceNeedsSetup }); v.Info.Setup != "" {
		t.Errorf("online: %+v", v)
	}
	if r := s.Observe(ctx, ObserveRequest{}); r.IsError() || r.Screen == nil {
		t.Errorf("phone_observe once free: %+v", r)
	}
}

//go:build wdasim

package gateway

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/DIYgod/pinky/internal/driver"
	"github.com/DIYgod/pinky/internal/driver/ios"
	"github.com/DIYgod/pinky/internal/policy"
	"github.com/DIYgod/pinky/internal/screen"
)

// TestReadListStaticWebSimulator compares the two paths on the same fixed,
// 100-item page. It is the repeatable performance check; public sites in
// read_list_web_sim_test.go remain real-world smoke tests.
func TestReadListStaticWebSimulator(t *testing.T) {
	base := os.Getenv("PINKY_WDA_URL")
	udid := os.Getenv("PINKY_SIM_UDID")
	if base == "" || udid == "" {
		t.Skip("PINKY_WDA_URL and PINKY_SIM_UDID are required")
	}
	var html strings.Builder
	html.WriteString(`<!doctype html><meta name="viewport" content="width=device-width">
<style>
body{margin:0;font:42px -apple-system;background:#fff;color:#111}
.item{height:420px;box-sizing:border-box;padding:40px 28px;border-bottom:2px solid #888}
h2{margin:0 0 24px;font-size:46px}
p{margin:0;color:#444}
</style>`)
	for i := 1; i <= 100; i++ {
		fmt.Fprintf(&html, `<section class="item"><h2><a href="#item%03d">Article %03d deterministic fixture title</a></h2><p>Stable excerpt %03d for list reading.</p></section>`,
			i, i, i)
	}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		_, _ = w.Write([]byte(html.String()))
	}))
	defer srv.Close()

	ctx, cancel := context.WithTimeout(context.Background(), 15*time.Minute)
	defer cancel()
	dev, err := ios.OpenWDAURL(ctx, base, os.Getenv("PINKY_MJPEG_URL"))
	if err != nil {
		t.Fatal(err)
	}
	defer dev.Close()
	g, err := New(Options{
		Providers:      []driver.Provider{&simulatorProvider{dev: dev}},
		Policy:         policy.Default(),
		TrustNewAgents: true,
		NoScreenshots:  true,
		DataDir:        t.TempDir(),
		DiscoverEvery:  time.Hour,
		SettleMax:      3 * time.Second,
		PollInterval:   100 * time.Millisecond,
		IdleTimeout:    15 * time.Minute,
	})
	if err != nil {
		t.Fatal(err)
	}
	defer g.Close()

	area := screen.Rect{X: 0, Y: 120, W: 1206, H: 2260}
	openWeb(t, udid, srv.URL)
	const fixtureScreens = 7
	old := measureWebSwipes(t, ctx, g, area, fixtureScreens, 30, 1000)
	openWeb(t, udid, srv.URL)
	next := measureWebList(t, ctx, g, area, fixtureScreens, 30)
	t.Logf("static 100-item fixture: old=%v (%d calls), phone_read_list=%v (%d screens, %d calls, stop %q), speedup %.2fx",
		old.elapsed.Round(time.Millisecond), old.calls, next.elapsed.Round(time.Millisecond),
		next.screens, next.calls, next.stop, float64(old.elapsed)/float64(next.elapsed))

	if next.screens < fixtureScreens || next.stop != "max_screens" {
		t.Fatalf("fixture scan: %+v", next)
	}
	for i := 1; i <= 5; i++ {
		title := fmt.Sprintf("Article %03d deterministic fixture title", i)
		if got := strings.Count(next.text, title); got != 1 {
			t.Fatalf("%q appeared %d times, want once\n%s", title, got, next.text)
		}
	}
}

package gateway

import (
	"context"
	"errors"
	"sync"
	"testing"
	"time"

	"github.com/DIYgod/pinky/internal/demo"
	"github.com/DIYgod/pinky/internal/driver"
	"github.com/DIYgod/pinky/internal/recording"
)

// streamer sends packets of the test stream with PTS on the stream's own
// clock and a little time between them, as a phone does.
type streamer struct {
	t           *testing.T
	src         *feedStream
	cfg         driver.Packet
	keys, plain []driver.Packet
	k, p        int
	start       time.Time
}

func newStreamer(t *testing.T, src *feedStream) *streamer {
	st := &streamer{t: t, src: src, start: time.Now()}
	for _, p := range testPackets(t) {
		switch {
		case p.Config:
			st.cfg = p
		case p.KeyFrame:
			st.keys = append(st.keys, p)
		default:
			st.plain = append(st.plain, p)
		}
	}
	return st
}

// config sends the configuration packet.
func (s *streamer) config() { s.src.send(s.cfg) }

// pictures sends n pictures, the first a key frame when key is set, and
// returns once the hub has taken them all.
func (s *streamer) pictures(n int, key bool) {
	s.t.Helper()
	for i := 0; i < n; i++ {
		var p driver.Packet
		if i == 0 && key {
			p = s.keys[s.k%len(s.keys)]
			s.k++
		} else {
			p = s.plain[s.p%len(s.plain)]
			s.p++
		}
		p.PTS = time.Since(s.start)
		s.src.send(p)
		time.Sleep(2 * time.Millisecond)
	}
	// The hub stamps a packet's arrival when it takes it from the stream,
	// and a read vouches only for what arrived before it: a hub that has
	// not run for a while on a busy machine would date the last pictures
	// after the test's next read.
	for deadline := time.Now().Add(5 * time.Second); len(s.src.ch) > 0; time.Sleep(time.Millisecond) {
		if time.Now().After(deadline) {
			s.t.Fatalf("the hub did not take %d pictures", len(s.src.ch))
		}
	}
	time.Sleep(5 * time.Millisecond)
}

func taskID(t *testing.T, g *Gateway, s *Session) string {
	t.Helper()
	g.mu.Lock()
	defer g.mu.Unlock()
	for _, l := range s.leases {
		return l.task.id
	}
	t.Fatal("the session has no task")
	return ""
}

func TestRecordingKeepsOnlyWhatReadsVouchFor(t *testing.T) {
	ctx := context.Background()
	v := newVideoDev("pixel")
	g := newVideoGateway(t, v)
	g.SetRecording(true)
	s, _ := connect(t, g, "Lunch")
	id := taskID(t, g, s)
	st := newStreamer(t, v.open(t))

	// A second of video, then a read of a plain screen: kept.
	st.config()
	st.pictures(10, true)
	mustStatus(t, s.Observe(ctx, ObserveRequest{}), StatusSettled)

	// A payment hands over to a blocked app: what came since the last
	// read is dropped, and so is what comes while it is in front.
	st.pictures(5, false)
	v.Show("wallet")
	s.Observe(ctx, ObserveRequest{})
	st.pictures(4, false)

	// Home again: writing resumes at a key frame, which the recorder asks
	// for (once at the start, once now).
	mustStatus(t, s.Act(ctx, Call{}, Action{Tool: "key", Key: "home"}), StatusSettled)
	// It asks on a goroutine of its own, through the hub's.
	for deadline := time.Now().Add(5 * time.Second); st.src.keyRequests() < 2; time.Sleep(time.Millisecond) {
		if time.Now().After(deadline) {
			t.Fatalf("%d key frame requests", st.src.keyRequests())
		}
	}
	st.pictures(3, false)
	st.pictures(5, true)

	// The task ends: one more read keeps the last part.
	mustStatus(t, s.Release(ctx, ReleaseRequest{}), StatusSettled)
	g.Flush()
	rec, err := g.Recording(ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	info, err := recording.Probe(rec.Path)
	if err != nil {
		t.Fatal(err)
	}
	if info.Frames != 15 || info.Width != 96 || info.Codec != driver.H264 {
		t.Fatalf("recorded %+v, want the 10 frames before the wallet and the 5 after the key frame", info)
	}
	if rec.Length <= 0 || rec.Start.IsZero() {
		t.Fatalf("recording %+v", rec)
	}
	var home bool
	for _, m := range rec.Marks {
		home = home || m.Text == "Pressed home"
		if m.At < 0 || m.At > rec.Length+time.Second {
			t.Fatalf("mark %+v outside the recording of %v", m, rec.Length)
		}
	}
	if !home || len(rec.Marks) < 3 {
		t.Fatalf("marks %+v", rec.Marks)
	}
}

func TestRecordingDropsTheTakeover(t *testing.T) {
	ctx := context.Background()
	v := newVideoDev("pixel")
	g := newVideoGateway(t, v)
	g.SetRecording(true)
	s, _ := connect(t, g, "Lunch")
	id := taskID(t, g, s)
	st := newStreamer(t, v.open(t))
	st.config()
	st.pictures(10, true)
	mustStatus(t, s.Observe(ctx, ObserveRequest{}), StatusSettled)
	// The person takes over (to type a password, say): nothing of it is
	// kept, even with a plain screen afterwards.
	st.pictures(4, false)
	if err := g.TakeOver("pixel"); err != nil {
		t.Fatal(err)
	}
	st.pictures(6, false)
	s.Observe(ctx, ObserveRequest{})
	if err := g.HandBack("pixel", ""); err != nil {
		t.Fatal(err)
	}
	// Stopped: no read afterwards, so what is held is not kept.
	st.pictures(5, true)
	if err := g.Stop("pixel"); err != nil {
		t.Fatal(err)
	}
	g.Flush()
	rec, err := g.Recording(ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	info, err := recording.Probe(rec.Path)
	if err != nil {
		t.Fatal(err)
	}
	if info.Frames != 10 {
		t.Fatalf("recorded %d frames, want only the 10 before the takeover", info.Frames)
	}
}

func TestNoRecordingWhenOff(t *testing.T) {
	ctx := context.Background()
	v := newVideoDev("pixel")
	g := newVideoGateway(t, v)
	s, _ := connect(t, g, "Lunch")
	id := taskID(t, g, s)
	select {
	case <-v.opened:
		t.Fatal("recording off, yet the stream opened")
	case <-time.After(50 * time.Millisecond):
	}
	mustStatus(t, s.Release(ctx, ReleaseRequest{}), StatusSettled)
	if _, err := g.Recording(ctx, id); !errors.Is(err, driver.ErrNotFound) {
		t.Fatalf("recording of an unrecorded task: %v", err)
	}
}

// Packets from before the task, which a late member of the hub gets to
// start from, are never written: the person may have used the phone.
func TestRecordingStartsWithTheTask(t *testing.T) {
	ctx := context.Background()
	v := newVideoDev("pixel")
	g := newVideoGateway(t, v)
	mirror, err := g.Stream(ctx, "pixel", driver.StreamOptions{})
	if err != nil {
		t.Fatal(err)
	}
	defer mirror.Close()
	st := newStreamer(t, v.open(t))
	st.config()
	st.pictures(8, true) // before the task; the hub keeps them for late viewers
	time.Sleep(10 * time.Millisecond)
	g.SetRecording(true)
	s, _ := connect(t, g, "Lunch")
	id := taskID(t, g, s)
	st.pictures(3, false) // still the old key frame's pictures: not decodable on their own
	st.pictures(4, true)
	mustStatus(t, s.Release(ctx, ReleaseRequest{}), StatusSettled)
	g.Flush()
	rec, err := g.Recording(ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	info, err := recording.Probe(rec.Path)
	if err != nil {
		t.Fatal(err)
	}
	if info.Frames != 4 {
		t.Fatalf("recorded %d frames, want the 4 from the task's first key frame", info.Frames)
	}
}

// A read that names no app (one app handing over to the next) vouches for
// nothing: what was held is dropped, as for a blocked app.
func TestRecordingDropsAnUnknownApp(t *testing.T) {
	ctx := context.Background()
	v := newVideoDev("pixel")
	g := newVideoGateway(t, v)
	g.SetRecording(true)
	s, _ := connect(t, g, "Lunch")
	id := taskID(t, g, s)
	st := newStreamer(t, v.open(t))
	st.config()
	st.pictures(10, true)
	mustStatus(t, s.Observe(ctx, ObserveRequest{}), StatusSettled)
	st.pictures(5, false)
	v.setNoApp(true)
	s.Observe(ctx, ObserveRequest{})
	v.setNoApp(false)
	st.pictures(3, false)
	mustStatus(t, s.Release(ctx, ReleaseRequest{}), StatusSettled)
	g.Flush()
	rec, err := g.Recording(ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	info, err := recording.Probe(rec.Path)
	if err != nil {
		t.Fatal(err)
	}
	if info.Frames != 10 {
		t.Fatalf("recorded %d frames, want the 10 before the unknown app", info.Frames)
	}
}

// Reads can overlap. A read that started earlier and is still running
// may show a blocked app, so a newer clean read writes nothing while it
// runs; when the older read then shows the blocked app, everything held is
// dropped. A drop from outside (a lock, a takeover) makes reads that were
// already running too old to resume the recording.
func TestRecordingOverlappingReads(t *testing.T) {
	t0 := time.Now().Add(-time.Hour) // packets on a clock of their own, in the past
	pkts := testPackets(t)
	at := func(ms int) time.Time { return t0.Add(time.Duration(ms) * time.Millisecond) }
	newVideo := func() *taskVideo {
		v := &taskVideo{floor: t0, needKey: true}
		v.cond = sync.NewCond(&v.mu)
		return v
	}
	send := func(v *taskVideo, p driver.Packet, ms int) {
		p.PTS = time.Duration(ms) * time.Millisecond
		v.packet(timedPacket{p: p, at: at(ms)}, driver.H264)
	}

	v := newVideo()
	send(v, pkts[0], 1)  // configuration
	send(v, pkts[1], 10) // key frame
	send(v, pkts[2], 20)
	old := v.readStarting(at(25)) // will see the blocked app
	send(v, pkts[3], 30)
	clean := v.readStarting(at(45))
	send(v, pkts[4], 50)
	v.read(clean, at(45), true)
	if len(v.ready) != 0 {
		t.Fatalf("%d packets written while an earlier read still ran", len(v.ready))
	}
	v.read(old, at(25), false)
	if len(v.held) != 0 || !v.paused || len(v.ready) != 0 {
		t.Fatalf("after the older read saw the blocked app: %d held, paused %v, %d written", len(v.held), v.paused, len(v.ready))
	}

	// In order, a clean read writes what came before it.
	v = newVideo()
	send(v, pkts[0], 1)
	send(v, pkts[1], 10)
	send(v, pkts[2], 20)
	r := v.readStarting(at(25))
	send(v, pkts[3], 30)
	v.read(r, at(25), true)
	if n := len(v.ready); n != 3 || len(v.held) != 1 {
		t.Fatalf("%d written, %d held; want the configuration, the key frame and a picture written, one held", n, len(v.held))
	}

	// The phone locks while a read runs: that read cannot resume the
	// recording, and what came before the lock and arrives later (a hub
	// replaying its last key frame) is never written.
	running := v.readStarting(at(40))
	v.pause()
	v.read(running, at(40), true)
	if !v.paused {
		t.Fatal("a read from before the lock resumed the recording")
	}
	now := stamp()
	fresh := v.readStarting(now)
	send(v, pkts[11], 60) // a key frame from before the lock, replayed
	v.read(fresh, now, true)
	send(v, pkts[12], 70)
	if len(v.held) != 0 || len(v.ready) != 3 {
		t.Fatalf("old packets taken after the lock: %d held, %d written", len(v.held), len(v.ready))
	}
}

// Packets that arrive after the task ended are not the task's.
func TestRecordingEndsWithTheTask(t *testing.T) {
	ctx := context.Background()
	v := newVideoDev("pixel")
	g := newVideoGateway(t, v)
	g.SetRecording(true)
	s, _ := connect(t, g, "Lunch")
	id := taskID(t, g, s)
	st := newStreamer(t, v.open(t))
	st.config()
	st.pictures(10, true)
	mustStatus(t, s.Release(ctx, ReleaseRequest{}), StatusSettled)
	st.pictures(6, false) // the person's own use, after the task
	g.Flush()
	rec, err := g.Recording(ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	info, err := recording.Probe(rec.Path)
	if err != nil {
		t.Fatal(err)
	}
	if info.Frames != 10 {
		t.Fatalf("recorded %d frames, want the 10 of the task", info.Frames)
	}
}

// On Windows, time.Now moves only with the system's clock tick, so events
// in one tick have the same time. The recorder took a picture of the
// person's own use that arrived in the tick the task ended in for the
// task's, and wrote it when the last read came a tick later; the same at
// the start, with pictures from before the task in the tick it started
// in; and a read that started in the tick the phone locked in, before the
// lock, resumed the recording.
func TestRecordingOnAWindowsClock(t *testing.T) {
	ctx := context.Background()
	t.Run("end", func(t *testing.T) {
		clk := windowsClock(t)
		v := newVideoDev("pixel")
		g := newVideoGateway(t, v)
		g.SetRecording(true)
		s, _ := connect(t, g, "Lunch")
		id := taskID(t, g, s)
		st := newStreamer(t, v.open(t))
		st.config()
		st.pictures(10, true)
		clk.tick()
		// The last read waits for an action in progress: it comes a tick
		// after the task ended.
		d := deviceOf(t, g, "pixel")
		d.act.Lock()
		mustStatus(t, s.Release(ctx, ReleaseRequest{}), StatusSettled)
		st.pictures(6, false) // the person's own use, in the tick the task ended in
		clk.tick()
		d.act.Unlock()
		g.Flush()
		if n := recordedFrames(t, g, id); n != 10 {
			t.Fatalf("recorded %d frames, want the 10 of the task", n)
		}
	})
	t.Run("start", func(t *testing.T) {
		clk := windowsClock(t)
		v := newVideoDev("pixel")
		g := newVideoGateway(t, v)
		mirror, err := g.Stream(ctx, "pixel", driver.StreamOptions{})
		if err != nil {
			t.Fatal(err)
		}
		defer mirror.Close()
		st := newStreamer(t, v.open(t))
		st.config()
		st.pictures(8, true) // the person's own use, which the hub keeps for late viewers
		g.SetRecording(true)
		s, _ := connect(t, g, "Lunch") // in the same tick
		id := taskID(t, g, s)
		clk.tick()
		st.pictures(3, false)
		st.pictures(4, true)
		clk.tick()
		mustStatus(t, s.Release(ctx, ReleaseRequest{}), StatusSettled)
		g.Flush()
		if n := recordedFrames(t, g, id); n != 4 {
			t.Fatalf("recorded %d frames, want the 4 from the task's first key frame", n)
		}
	})
	t.Run("lock", func(t *testing.T) {
		windowsClock(t) // every stamp in one tick
		pkts := testPackets(t)
		v := &taskVideo{floor: stamp(), needKey: true}
		v.cond = sync.NewCond(&v.mu)
		send := func(p driver.Packet) { v.packet(timedPacket{p: p, at: stamp()}, driver.H264) }
		send(pkts[0])
		send(pkts[1])
		start := stamp()
		running := v.readStarting(start)
		v.pause() // the phone locks
		send(pkts[2])
		v.read(running, start, true) // the screen it saw before the lock
		if !v.paused || len(v.held) != 0 || len(v.ready) != 0 {
			t.Fatalf("a read from before the lock resumed the recording: paused %v, %d held, %d written", v.paused, len(v.held), len(v.ready))
		}
	})
}

// A read confirmed the recording's first pictures, which the write loop
// has yet to write (creating the file took a while on Windows): the
// recording counts as held, so a release right then asks the person about
// it rather than leave it out.
func TestRecordedBeforeWritten(t *testing.T) {
	pkts := testPackets(t)
	v := &taskVideo{floor: stamp(), needKey: true}
	v.cond = sync.NewCond(&v.mu)
	if v.recorded() {
		t.Fatal("recorded before any picture")
	}
	for _, p := range pkts[:4] {
		v.packet(timedPacket{p: p, at: stamp()}, driver.H264)
	}
	if v.recorded() {
		t.Fatal("recorded with pictures no read confirmed")
	}
	start := stamp()
	v.read(v.readStarting(start), start, true)
	if _, ok := v.view(); ok || len(v.ready) == 0 {
		t.Fatalf("view %v, %d ready", ok, len(v.ready))
	}
	if !v.recorded() {
		t.Fatal("pictures on their way to the file do not count")
	}
}

func deviceOf(t *testing.T, g *Gateway, id string) *device {
	t.Helper()
	g.mu.Lock()
	defer g.mu.Unlock()
	d := g.findDeviceLocked(id)
	if d == nil {
		t.Fatalf("no device %q", id)
	}
	return d
}

func recordedFrames(t *testing.T, g *Gateway, id string) int {
	t.Helper()
	rec, err := g.Recording(context.Background(), id)
	if err != nil {
		t.Fatal(err)
	}
	info, err := recording.Probe(rec.Path)
	if err != nil {
		t.Fatal(err)
	}
	return info.Frames
}

// closingDev is a phone's device that stops working once closed, as a
// driver's does after the phone dropped; every Open returns a new one.
type closingDev struct {
	*videoDev
	mu     sync.Mutex
	closed bool
}

func (c *closingDev) Stream(ctx context.Context, opt driver.StreamOptions) (driver.Stream, error) {
	c.mu.Lock()
	closed := c.closed
	c.mu.Unlock()
	if closed {
		return nil, errors.New("device closed")
	}
	return c.videoDev.Stream(ctx, opt)
}

func (c *closingDev) Close() error {
	c.mu.Lock()
	c.closed = true
	c.mu.Unlock()
	return nil
}

type closingProvider struct {
	*demo.Provider
	v *videoDev
}

func (p closingProvider) Open(ctx context.Context, id string) (driver.Device, error) {
	if _, err := p.Provider.Open(ctx, id); err != nil {
		return nil, err
	}
	return &closingDev{videoDev: p.v}, nil
}

// After the phone drops and comes back, the recording opens the stream of
// the new connection, not the closed one.
func TestRecordingAfterReconnect(t *testing.T) {
	ctx := context.Background()
	v := newVideoDev("pixel")
	g := newVideoGateway(t, v, func(o *Options) {
		o.Providers = []driver.Provider{closingProvider{demo.NewProvider(driver.Android, v.Device), v}}
		o.DiscoverEvery = 10 * time.Millisecond
	})
	g.SetRecording(true)
	s, _ := connect(t, g, "Lunch")
	id := taskID(t, g, s)
	first := v.open(t)
	v.SetOffline(true)
	waitStatus(t, g, DeviceOffline)
	first.end(errors.New("unplugged"))
	v.SetOffline(false)
	waitStatus(t, g, DeviceWorking)
	st := newStreamer(t, v.open(t))
	// Nothing is written until a read after the new stream vouches for it.
	mustStatus(t, s.Observe(ctx, ObserveRequest{}), StatusSettled)
	st.config()
	st.pictures(8, true)
	mustStatus(t, s.Release(ctx, ReleaseRequest{}), StatusSettled)
	g.Flush()
	rec, err := g.Recording(ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	if info, err := recording.Probe(rec.Path); err != nil || info.Frames != 8 {
		t.Fatalf("after the reconnect: %+v, %v", info, err)
	}
}

func waitStatus(t *testing.T, g *Gateway, st DeviceStatus) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		if g.Devices()[0].Status == st {
			return
		}
		time.Sleep(5 * time.Millisecond)
	}
	t.Fatalf("the phone is %s, not %s", g.Devices()[0].Status, st)
}

//go:build linux

package secret

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/godbus/dbus/v5"
)

// The tests run the store against a fake Secret Service on a private
// session bus (dbus-daemon), whose prompts answer by themselves as the
// test says: no keyring daemon, display or person is needed.

// startBus starts a private session bus and points the process at it.
func startBus(t *testing.T) string {
	t.Helper()
	daemon, err := exec.LookPath("dbus-daemon")
	if err != nil {
		t.Skip("no dbus-daemon to run a private session bus")
	}
	dir := t.TempDir()
	config := filepath.Join(dir, "bus.conf")
	if err := os.WriteFile(config, []byte(`<!DOCTYPE busconfig PUBLIC "-//freedesktop//DTD D-Bus Bus Configuration 1.0//EN"
 "http://www.freedesktop.org/standards/dbus/1.0/busconfig.dtd">
<busconfig>
  <type>session</type>
  <listen>unix:path=`+filepath.Join(dir, "bus")+`</listen>
  <auth>EXTERNAL</auth>
  <policy context="default">
    <allow send_destination="*" eavesdrop="true"/>
    <allow eavesdrop="true"/>
    <allow own="*"/>
  </policy>
</busconfig>
`), 0o600); err != nil {
		t.Fatal(err)
	}
	cmd := exec.Command(daemon, "--config-file="+config, "--nofork", "--print-address=1")
	out, err := cmd.StdoutPipe()
	if err != nil {
		t.Fatal(err)
	}
	if err := cmd.Start(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		cmd.Process.Kill()
		cmd.Wait()
	})
	line, err := bufio.NewReader(out).ReadString('\n')
	if err != nil {
		t.Fatalf("dbus-daemon: %v", err)
	}
	addr := strings.TrimSpace(line)
	t.Setenv("DBUS_SESSION_BUS_ADDRESS", addr)
	return addr
}

// fakeService is a Secret Service in memory. answer decides how its
// prompts end: "accept", "dismiss", or "wait" (until Dismiss).
type fakeService struct {
	conn *dbus.Conn

	mu          sync.Mutex
	answer      string
	lockRefuses string // "locked": Lock fails on a locked collection, as KWallet's does; "always": every Lock fails
	prompts     int    // prompts shown
	dismissed   int    // prompts dismissed by the client
	next        int
	collections map[dbus.ObjectPath]*fakeCollection
	items       map[dbus.ObjectPath]*fakeItem
	pending     map[dbus.ObjectPath]func(accept bool) dbus.Variant
}

type fakeCollection struct {
	label  string
	locked bool
}

type fakeItem struct {
	coll   dbus.ObjectPath
	attrs  map[string]string
	secret []byte
}

func startFakeService(t *testing.T, addr string) *fakeService {
	t.Helper()
	conn, err := dbus.Connect(addr)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { conn.Close() })
	f := &fakeService{
		conn:        conn,
		answer:      "accept",
		collections: map[dbus.ObjectPath]*fakeCollection{},
		items:       map[dbus.ObjectPath]*fakeItem{},
		pending:     map[dbus.ObjectPath]func(bool) dbus.Variant{},
	}
	for _, e := range []struct {
		v     any
		iface string
	}{
		{fakeServiceAPI{f}, ssService},
		{fakeCollectionAPI{f}, ssCollection},
		{fakeItemAPI{f}, ssItem},
		{fakePromptAPI{f}, ssPrompt},
		{fakeSessionAPI{f}, ssSession},
		{fakeProperties{f}, "org.freedesktop.DBus.Properties"},
	} {
		if err := conn.ExportSubtree(e.v, ssPath, e.iface); err != nil {
			t.Fatal(err)
		}
	}
	if reply, err := conn.RequestName(ssName, dbus.NameFlagDoNotQueue); err != nil || reply != dbus.RequestNameReplyPrimaryOwner {
		t.Fatalf("own %s: %v %v", ssName, reply, err)
	}
	return f
}

func (f *fakeService) set(answer string) {
	f.mu.Lock()
	f.answer = answer
	f.mu.Unlock()
}

func (f *fakeService) counts() (prompts, dismissed int) {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.prompts, f.dismissed
}

// newPrompt returns a prompt whose acceptance runs done; f.mu is held.
func (f *fakeService) newPrompt(done func(accept bool) dbus.Variant) dbus.ObjectPath {
	f.next++
	p := dbus.ObjectPath(fmt.Sprintf("%s/prompt/p%d", ssPath, f.next))
	f.pending[p] = done
	return p
}

func (f *fakeService) complete(p dbus.ObjectPath, accept bool) {
	f.mu.Lock()
	done := f.pending[p]
	delete(f.pending, p)
	var result dbus.Variant
	if done != nil {
		result = done(accept)
	}
	f.mu.Unlock()
	if done == nil {
		return
	}
	if !accept {
		result = dbus.MakeVariant("")
	}
	f.conn.Emit(p, ssPrompt+".Completed", !accept, result)
}

type fakeServiceAPI struct{ f *fakeService }

func (a fakeServiceAPI) OpenSession(algorithm string, input dbus.Variant) (dbus.Variant, dbus.ObjectPath, *dbus.Error) {
	if algorithm != "plain" {
		return dbus.Variant{}, "", dbus.NewError("org.freedesktop.DBus.Error.NotSupported", nil)
	}
	return dbus.MakeVariant(""), ssPath + "/session/s1", nil
}

func (a fakeServiceAPI) CreateCollection(props map[string]dbus.Variant, alias string) (dbus.ObjectPath, dbus.ObjectPath, *dbus.Error) {
	label, _ := props[ssCollection+".Label"].Value().(string)
	a.f.mu.Lock()
	defer a.f.mu.Unlock()
	p := a.f.newPrompt(func(accept bool) dbus.Variant {
		if !accept {
			return dbus.MakeVariant(noPrompt)
		}
		a.f.next++
		path := dbus.ObjectPath(fmt.Sprintf("%s/collection/c%d", ssPath, a.f.next))
		a.f.collections[path] = &fakeCollection{label: label}
		return dbus.MakeVariant(path)
	})
	return noPrompt, p, nil
}

func (a fakeServiceAPI) Unlock(objects []dbus.ObjectPath) ([]dbus.ObjectPath, dbus.ObjectPath, *dbus.Error) {
	a.f.mu.Lock()
	defer a.f.mu.Unlock()
	locked := false
	for _, o := range objects {
		if c := a.f.collections[o]; c != nil && c.locked {
			locked = true
		}
	}
	if !locked {
		return objects, noPrompt, nil
	}
	p := a.f.newPrompt(func(accept bool) dbus.Variant {
		if accept {
			for _, o := range objects {
				if c := a.f.collections[o]; c != nil {
					c.locked = false
				}
			}
		}
		return dbus.MakeVariant(objects)
	})
	return []dbus.ObjectPath{}, p, nil
}

// SearchItems finds items in every collection: those of unlocked
// collections first, then those of locked ones.
func (a fakeServiceAPI) SearchItems(attrs map[string]string) ([]dbus.ObjectPath, []dbus.ObjectPath, *dbus.Error) {
	a.f.mu.Lock()
	defer a.f.mu.Unlock()
	unlocked, locked := []dbus.ObjectPath{}, []dbus.ObjectPath{}
	for path, it := range a.f.items {
		match := true
		for k, v := range attrs {
			match = match && it.attrs[k] == v
		}
		switch {
		case !match:
		case a.f.collections[it.coll].locked:
			locked = append(locked, path)
		default:
			unlocked = append(unlocked, path)
		}
	}
	return unlocked, locked, nil
}

func (a fakeServiceAPI) Lock(objects []dbus.ObjectPath) ([]dbus.ObjectPath, dbus.ObjectPath, *dbus.Error) {
	a.f.mu.Lock()
	defer a.f.mu.Unlock()
	for _, o := range objects {
		c := a.f.collections[o]
		if c == nil {
			continue
		}
		if a.f.lockRefuses == "always" || a.f.lockRefuses == "locked" && c.locked {
			return nil, "", dbus.NewError("org.freedesktop.DBus.Error.Failed", []any{"Can't lock object at path " + string(o)})
		}
		c.locked = true
	}
	return objects, noPrompt, nil
}

type fakeCollectionAPI struct{ f *fakeService }

func (a fakeCollectionAPI) SearchItems(msg dbus.Message, attrs map[string]string) ([]dbus.ObjectPath, *dbus.Error) {
	coll := msg.Headers[dbus.FieldPath].Value().(dbus.ObjectPath)
	a.f.mu.Lock()
	defer a.f.mu.Unlock()
	found := []dbus.ObjectPath{}
	for path, it := range a.f.items {
		match := it.coll == coll
		for k, v := range attrs {
			match = match && it.attrs[k] == v
		}
		if match {
			found = append(found, path)
		}
	}
	return found, nil
}

func (a fakeCollectionAPI) CreateItem(msg dbus.Message, props map[string]dbus.Variant, secret ssSecret, replace bool) (dbus.ObjectPath, dbus.ObjectPath, *dbus.Error) {
	coll := msg.Headers[dbus.FieldPath].Value().(dbus.ObjectPath)
	attrs, _ := props[ssItem+".Attributes"].Value().(map[string]string)
	a.f.mu.Lock()
	defer a.f.mu.Unlock()
	if c := a.f.collections[coll]; c == nil {
		return "", "", dbus.NewError("org.freedesktop.Secret.Error.NoSuchObject", nil)
	} else if c.locked {
		return "", "", dbus.NewError("org.freedesktop.Secret.Error.IsLocked", nil)
	}
	if replace {
		for path, it := range a.f.items {
			if it.coll == coll && it.attrs["service"] == attrs["service"] && it.attrs["account"] == attrs["account"] {
				it.secret = append([]byte(nil), secret.Value...)
				return path, noPrompt, nil
			}
		}
	}
	a.f.next++
	path := dbus.ObjectPath(fmt.Sprintf("%s/i%d", coll, a.f.next))
	a.f.items[path] = &fakeItem{coll: coll, attrs: attrs, secret: append([]byte(nil), secret.Value...)}
	return path, noPrompt, nil
}

type fakeItemAPI struct{ f *fakeService }

func (a fakeItemAPI) GetSecret(msg dbus.Message, session dbus.ObjectPath) (ssSecret, *dbus.Error) {
	path := msg.Headers[dbus.FieldPath].Value().(dbus.ObjectPath)
	a.f.mu.Lock()
	defer a.f.mu.Unlock()
	it := a.f.items[path]
	if it == nil {
		return ssSecret{}, dbus.NewError("org.freedesktop.Secret.Error.NoSuchObject", nil)
	}
	if a.f.collections[it.coll].locked {
		return ssSecret{}, dbus.NewError("org.freedesktop.Secret.Error.IsLocked", nil)
	}
	return ssSecret{Session: session, Parameters: []byte{}, Value: it.secret, ContentType: "text/plain"}, nil
}

func (a fakeItemAPI) Delete(msg dbus.Message) (dbus.ObjectPath, *dbus.Error) {
	path := msg.Headers[dbus.FieldPath].Value().(dbus.ObjectPath)
	a.f.mu.Lock()
	defer a.f.mu.Unlock()
	it := a.f.items[path]
	if it == nil {
		return "", dbus.NewError("org.freedesktop.Secret.Error.NoSuchObject", nil)
	}
	if a.f.collections[it.coll].locked {
		return "", dbus.NewError("org.freedesktop.Secret.Error.IsLocked", nil)
	}
	delete(a.f.items, path)
	return noPrompt, nil
}

type fakePromptAPI struct{ f *fakeService }

func (a fakePromptAPI) Prompt(msg dbus.Message, window string) *dbus.Error {
	p := msg.Headers[dbus.FieldPath].Value().(dbus.ObjectPath)
	a.f.mu.Lock()
	a.f.prompts++
	answer := a.f.answer
	a.f.mu.Unlock()
	if answer != "wait" {
		go func() {
			time.Sleep(10 * time.Millisecond)
			a.f.complete(p, answer == "accept")
		}()
	}
	return nil
}

func (a fakePromptAPI) Dismiss(msg dbus.Message) *dbus.Error {
	p := msg.Headers[dbus.FieldPath].Value().(dbus.ObjectPath)
	a.f.mu.Lock()
	a.f.dismissed++
	a.f.mu.Unlock()
	a.f.complete(p, false)
	return nil
}

type fakeSessionAPI struct{ f *fakeService }

func (fakeSessionAPI) Close() *dbus.Error { return nil }

type fakeProperties struct{ f *fakeService }

func (a fakeProperties) Get(msg dbus.Message, iface, name string) (dbus.Variant, *dbus.Error) {
	path := msg.Headers[dbus.FieldPath].Value().(dbus.ObjectPath)
	a.f.mu.Lock()
	defer a.f.mu.Unlock()
	switch iface + "." + name {
	case ssService + ".Collections":
		paths := []dbus.ObjectPath{}
		for p := range a.f.collections {
			paths = append(paths, p)
		}
		return dbus.MakeVariant(paths), nil
	case ssCollection + ".Label":
		if c := a.f.collections[path]; c != nil {
			return dbus.MakeVariant(c.label), nil
		}
	case ssCollection + ".Locked":
		if c := a.f.collections[path]; c != nil {
			return dbus.MakeVariant(c.locked), nil
		}
	}
	return dbus.Variant{}, dbus.NewError("org.freedesktop.DBus.Error.UnknownProperty", nil)
}

func TestSecretServiceSaveRevealDelete(t *testing.T) {
	f := startFakeService(t, startBus(t))
	s := newSecretService("app.pinky.desktop.test", "Pinky test")
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()

	// An item of another keyring with the same attributes is not Pinky's.
	login := ssPath + "/collection/login"
	f.mu.Lock()
	f.collections[login] = &fakeCollection{label: "Login"}
	f.items[login+"/1"] = &fakeItem{coll: login, secret: []byte("not this"),
		attrs: map[string]string{"service": "app.pinky.desktop.test", "account": "pin:a"}}
	f.mu.Unlock()

	if s.Has("pin:a") {
		t.Fatal("Has before Save")
	}
	if _, err := s.Reveal(ctx, "pin:a", "unlock A"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("Reveal before Save = %v, want ErrNotFound", err)
	}
	// The first Save creates the keyring, which asks the person.
	if err := s.Save("pin:a", "1234"); err != nil {
		t.Fatal(err)
	}
	if p, _ := f.counts(); p != 1 {
		t.Fatalf("%d prompts for the first Save, want 1 (create the keyring)", p)
	}
	if !s.Has("pin:a") || s.Has("pin:b") {
		t.Fatalf("Has: pin:a %t, pin:b %t", s.Has("pin:a"), s.Has("pin:b"))
	}
	// The keyring is locked after Save, and Reveal asks to unlock it.
	got, err := s.Reveal(ctx, "pin:a", "unlock A")
	if err != nil || got != "1234" {
		t.Fatalf("Reveal = %q, %v", got, err)
	}
	if p, _ := f.counts(); p != 2 {
		t.Fatalf("%d prompts after Reveal, want 2", p)
	}
	// Saving again replaces the secret (and asks to unlock).
	if err := s.Save("pin:a", "5678"); err != nil {
		t.Fatal(err)
	}
	if got, err := s.Reveal(ctx, "pin:a", "unlock A"); err != nil || got != "5678" {
		t.Fatalf("Reveal after the second Save = %q, %v", got, err)
	}

	// Cancelling the prompt is ErrCancelled.
	f.set("dismiss")
	if _, err := s.Reveal(ctx, "pin:a", "unlock A"); !errors.Is(err, ErrCancelled) {
		t.Fatalf("Reveal with a dismissed prompt = %v, want ErrCancelled", err)
	}
	// A context that ends takes the prompt away.
	f.set("wait")
	short, cancelShort := context.WithTimeout(ctx, 200*time.Millisecond)
	_, err = s.Reveal(short, "pin:a", "unlock A")
	cancelShort()
	if !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Reveal past its context = %v, want DeadlineExceeded", err)
	}
	if _, d := f.counts(); d != 1 {
		t.Fatalf("%d prompts dismissed, want 1", d)
	}

	f.set("accept")
	if err := s.Delete("pin:a"); err != nil {
		t.Fatal(err)
	}
	if s.Has("pin:a") {
		t.Fatal("Has after Delete")
	}
	if err := s.Delete("pin:a"); err != nil {
		t.Fatalf("Delete of nothing: %v", err)
	}
}

// KWallet's Secret Service refuses to lock a collection that is locked
// already; Reveal still unlocks it, asking the person.
func TestSecretServiceLockRefusedWhenLocked(t *testing.T) {
	f := startFakeService(t, startBus(t))
	s := newSecretService("app.pinky.desktop.test", "Pinky test")
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	if err := s.Save("pin:a", "1234"); err != nil {
		t.Fatal(err)
	}
	f.mu.Lock()
	f.lockRefuses = "locked"
	f.mu.Unlock()
	got, err := s.Reveal(ctx, "pin:a", "unlock A")
	if err != nil || got != "1234" {
		t.Fatalf("Reveal of a locked keyring = %q, %v", got, err)
	}
	if p, _ := f.counts(); p != 2 {
		t.Fatalf("%d prompts after Reveal, want 2", p)
	}
	// An open keyring is locked first, so Reveal asks all the same.
	f.mu.Lock()
	for _, c := range f.collections {
		c.locked = false
	}
	f.mu.Unlock()
	if got, err := s.Reveal(ctx, "pin:a", "unlock A"); err != nil || got != "1234" {
		t.Fatalf("Reveal of an open keyring = %q, %v", got, err)
	}
	if p, _ := f.counts(); p != 3 {
		t.Fatalf("%d prompts after Reveal of an open keyring, want 3", p)
	}
}

// A keyring that stays open because the service won't lock it is not
// revealed without asking.
func TestSecretServiceLockRefusedWhenOpen(t *testing.T) {
	f := startFakeService(t, startBus(t))
	s := newSecretService("app.pinky.desktop.test", "Pinky test")
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	if err := s.Save("pin:a", "1234"); err != nil {
		t.Fatal(err)
	}
	f.mu.Lock()
	f.lockRefuses = "always"
	for _, c := range f.collections {
		c.locked = false
	}
	f.mu.Unlock()
	if got, err := s.Reveal(ctx, "pin:a", "unlock A"); err == nil {
		t.Fatalf("Reveal of a keyring that won't lock = %q, want an error", got)
	}
}

func TestSecretServiceCancelCreate(t *testing.T) {
	f := startFakeService(t, startBus(t))
	f.set("dismiss")
	s := newSecretService("app.pinky.desktop.test", "Pinky test")
	if err := s.Save("pin:a", "1234"); !errors.Is(err, ErrCancelled) {
		t.Fatalf("Save with the keyring's creation dismissed = %v, want ErrCancelled", err)
	}
