		t.Fatalf("apps listed under another choice: %q", tt.Texts())
	}
	chosen := func() string { return ga.agents.apps[n.ID] }
	frames := func() { tt.Frame(); tt.Frame() }
	click := func(s string) {
		t.Helper()
		if err := tt.Click(s); err != nil {
			t.Fatalf("%v: %q", err, tt.Texts())
