	cl := sdk.NewClient(&sdk.Implementation{Name: "claude-code", Version: "1"}, nil)
	cs, err := cl.Connect(context.Background(), &sdk.IOTransport{Reader: io.NopCloser(br), Writer: c}, nil)
	if err != nil {
