			{Role: screen.RoleOther, Label: "Security", Bounds: screen.Rect{X: 0, Y: 0, W: 1080, H: 2000}},
			treeText("Steps today", 40, 300, 400, 60),
			treeText("12345", 40, 380, 400, 80),
		},
		want: "Security\nSteps today\n12345\n",
	}, {
		name: "a price list in a shop",
		in: []screen.Element{
			treeText("Promo code", 40, 300, 400, 60),
			treeText("¥1299", 40, 380, 400, 60),
			treeText("1299", 500, 380, 200, 60),
		},
		want: "Promo code\n¥1299\n1299\n",
	}}
	for _, c := range cases {
		in := append([]screen.Element(nil), c.in...)
		got, n := MaskElements(in)
		if labels(got) != c.want {
			t.Errorf("%s:\n got:\n%s\nwant:\n%s", c.name, labels(got), c.want)
		}
		if want := strings.Count(c.want, "[masked]"); n != want {
			t.Errorf("%s: masked %d, want %d", c.name, n, want)
		}
		if labels(in) != labels(c.in) {
			t.Errorf("%s: changed its input", c.name)
		}
	}
}

func TestMaskScreenFollowsTheSetting(t *testing.T) {
	e := Default()
	if !e.HideCodes() {
		t.Fatal("codes are not hidden by default")
	}
	s := &screen.Screen{Elements: []screen.Element{treeText("Your code is 482913", 0, 0, 100, 40)}}
	if n := e.MaskScreen(s); n != 1 || s.Elements[0].Label != "Your code is ••••••" || !s.Elements[0].Masked {
		t.Fatalf("masked %d: %+v", n, s.Elements)
	}
	off := false
	e = New(File{MaskCodes: &off}, nil)
	s = &screen.Screen{Elements: []screen.Element{treeText("Your code is 482913", 0, 0, 100, 40)}}
	if n := e.MaskScreen(s); n != 0 || s.Elements[0].Label != "Your code is 482913" {
		t.Fatalf("masked with the setting off: %+v", s.Elements)
	}
}

func TestFilterEventsMasksToasts(t *testing.T) {
	got := Default().FilterEvents([]screen.Event{{Kind: screen.EventToast, Text: "Code 482913 copied"}})
	if got[0].Text != "Code •••••• copied" {
		t.Fatalf("toast: %q", got[0].Text)
	}
}

package telemetry

import (
	"context"
	"os"
	"testing"
	"time"
)

// TestAgainstTheWorker sends a real usage report and a real crash report
// to a running telemetry Worker (worker/), for a check before deploying:
//
//	cd worker && wrangler d1 migrations apply pinky-telemetry --local && wrangler dev
//	PINKY_TELEMETRY_TEST_URL=http://127.0.0.1:8787 go test -run TestAgainstTheWorker ./internal/telemetry
//
// The reports are stored; never point it at the deployed Worker
// (worker/smoke.sh checks that one with test reports).
func TestAgainstTheWorker(t *testing.T) {
	url := os.Getenv("PINKY_TELEMETRY_TEST_URL")
	if url == "" {
		t.Skip("set PINKY_TELEMETRY_TEST_URL to a Worker run with wrangler dev")
	}
	t.Setenv("DO_NOT_TRACK", "")
	dir := t.TempDir()
	runChildTo(t, "panic", dir, "daemon")
	cr := capture(t, dir)
	clk := newClock()
	clk.t = time.Now().Add(-25 * time.Hour)
	c := Open(Options{Dir: dir, Version: "0.0.0-dev", Backend: &HTTP{URL: url, Version: "0.0.0-dev"}, Crashes: cr, Usage: true, Now: clk.now})
	c.Count("app.starts")
	c.Add("tools.phone_tap", 7)
	c.SeePhone("android.wifi", "3e8be48e")
	c.Max("phones.max_online", 1)
	clk.advance(25 * time.Hour)
	ctx := context.Background()
	c.sendUsage(ctx)
	if c.st.Failures != 0 || len(c.Report().Counts) != 0 {
		t.Fatalf("usage not sent: failures %d, counts %v", c.st.Failures, c.Report().Counts)
	}
	c.sendCrashes(ctx)
	if left := c.Crashes(); len(left) != 0 {
		t.Fatalf("crash report not sent: %+v", left)
	}
	t.Logf("install id %s, crash %s", c.InstallID(), cr.Found()[0].ID)
}
